#!/usr/bin/env Rscript
# Improved DHARMa diagnostics - tries multiple model types
# Author: Generated by LLM to fix model issues
# Date: 2025

library(MASS)       # For glm.nb, glm.zig
library(DHARMa)     # For residual diagnostics  
library(jsonlite)   # For reading metadata
library(pscl)       # For zero-inflation models
library(yaml)       # For reading config

# ============================================================================
# Configuration  
# ============================================================================

CACHE_DIR <- "/scratch/yl998/.cache/dharma"
OUTPUT_DIR <- "/scratch/yl998/dharma_results_improved"
N_SIMULATIONS <- 250  # Reduced for faster testing

# ============================================================================
# Functions
# ============================================================================

load_cache <- function() {
  "Load preprocessed data from Julia cache"
  
  # Check cache exists
  meta_file <- file.path(CACHE_DIR, "dharma_meta.json")
  if (!file.exists(meta_file)) {
    stop(sprintf("Cache not found: %s", meta_file))
  }
  
  # Load metadata
  meta <- fromJSON(meta_file)
  cat("Loaded metadata from:", meta_file, "\n")
  
  # Load CSV data
  csv_file <- file.path(CACHE_DIR, "dharma_data.csv")
  if (!file.exists(csv_file)) {
    stop(sprintf("CSV data file not found: %s", csv_file))
  }
  
  df <- read.csv(csv_file, stringsAsFactors = FALSE)
  cat("Loaded data:", nrow(df), "rows,", ncol(df), "columns\n")
  cat("Sample fraction:", round(meta$sample_frac * 100, 1), "%\n\n")
  
  return(list(data = df, meta = meta))
}

build_formula <- function(meta, model_type = "base") {
  "Build single formula for testing different model types"
  
  # Base features
  climate <- c("bio01_std", "bio04_std", "bio12_std", "bio15_std")
  elevation <- c("elevation_std", "elevation_std_sq")
  mesf <- meta$mesf_columns
  base <- c(climate, elevation, mesf)
  
  # Read config to determine response variable
  config <- yaml::read_yaml("../../../src/config/ml/ml_config.yml")
  response_type <- config$method1$response
  if (is.null(response_type)) {
    response_type <- "fungi"  # Default if not specified
  }
  
  # Set response variable and biotic predictors based on config
  if (response_type == "fungi") {
    response_var <- "fungi_richness_int"
    biotic <- c("plants_richness_std", "vertebrates_richness_std")
  } else if (response_type == "plants") {
    response_var <- "plants_richness_int"
    biotic <- c("fungi_richness_std", "vertebrates_richness_std")
  } else if (response_type == "vertebrates") {
    response_var <- "vertebrates_richness_int"
    biotic <- c("fungi_richness_std", "plants_richness_std")
  } else {
    stop(paste("Unknown response type:", response_type))
  }
  
  # Use method1_full as our test formula (best AIC from previous run)
  formula_str <- paste(response_var, "~", paste(c(base, biotic), collapse = " + "))
  
  return(formula_str)
}

fit_multiple_models <- function(formula_str, data) {
  "Fit and compare multiple model types"
  
  cat("Testing multiple model types with formula:\n")
  cat(formula_str, "\n\n")
  
  results <- list()
  
  # 1. Original negative binomial
  cat("1. Negative binomial (glm.nb)...\n")
  tryCatch({
    model_nb <- glm.nb(as.formula(formula_str), data = data)
    results$negbin <- list(
      model = model_nb,
      type = "negbin", 
      aic = AIC(model_nb),
      theta = model_nb$theta
    )
    cat("   AIC:", round(AIC(model_nb), 1), "Theta:", round(model_nb$theta, 3), "\n")
  }, error = function(e) cat("   Failed:", e$message, "\n"))
  
  # 2. Poisson (simpler)
  cat("2. Poisson (glm)...\n") 
  tryCatch({
    model_pois <- glm(as.formula(formula_str), data = data, family = poisson())
    results$poisson <- list(
      model = model_pois,
      type = "poisson",
      aic = AIC(model_pois),
      theta = NA
    )
    cat("   AIC:", round(AIC(model_pois), 1), "\n")
  }, error = function(e) cat("   Failed:", e$message, "\n"))
  
  # 3. Zero-inflated Poisson
  cat("3. Zero-inflated Poisson (zeroinfl)...\n")
  tryCatch({
    model_zip <- zeroinfl(as.formula(formula_str), data = data, dist = "poisson")
    results$zip <- list(
      model = model_zip,
      type = "zip",
      aic = AIC(model_zip),
      theta = NA
    )
    cat("   AIC:", round(AIC(model_zip), 1), "\n")
  }, error = function(e) cat("   Failed:", e$message, "\n"))
  
  # 4. Zero-inflated Negative Binomial  
  cat("4. Zero-inflated Negative Binomial (zeroinfl)...\n")
  tryCatch({
    model_zinb <- zeroinfl(as.formula(formula_str), data = data, dist = "negbin")
    results$zinb <- list(
      model = model_zinb,
      type = "zinb", 
      aic = AIC(model_zinb),
      theta = NA
    )
    cat("   AIC:", round(AIC(model_zinb), 1), "\n")
  }, error = function(e) cat("   Failed:", e$message, "\n"))
  
  cat("\n")
  return(results)
}

run_dharma_test <- function(model_result, model_name) {
  "Run DHARMa diagnostics on a model"
  
  cat("DHARMa diagnostics for:", model_name, "\n")
  cat("Model type:", model_result$type, "\n")
  cat("AIC:", round(model_result$aic, 1), "\n")
  
  # DHARMa simulations
  start_time <- Sys.time()
  res <- simulateResiduals(
    fittedModel = model_result$model,
    n = N_SIMULATIONS,
    plot = FALSE,
    seed = 123
  )
  sim_time <- difftime(Sys.time(), start_time, units = "secs")
  cat("Simulation time:", round(sim_time, 1), "seconds\n")
  
  # Run tests
  test_unif <- testUniformity(res, plot = FALSE)
  test_disp <- testDispersion(res, plot = FALSE)
  test_out <- testOutliers(res, plot = FALSE)
  test_zero <- testZeroInflation(res, plot = FALSE)
  
  cat("Tests: Unif=", sprintf("%.4f", test_unif$p.value),
      " Disp=", sprintf("%.4f", test_disp$p.value), 
      " Out=", sprintf("%.4f", test_out$p.value),
      " Zero=", sprintf("%.4f", test_zero$p.value), "\n")
  
  # Overall pass/fail
  all_pass <- all(c(test_unif$p.value, test_disp$p.value, 
                    test_out$p.value, test_zero$p.value) > 0.05)
  
  cat("Overall:", ifelse(all_pass, "✅ PASS", "❌ FAIL"), "\n\n")
  
  return(list(
    model_name = model_name,
    model_type = model_result$type,
    aic = model_result$aic,
    theta = model_result$theta,
    dharma_res = res,
    tests = list(
      uniformity = test_unif$p.value,
      dispersion = test_disp$p.value,
      outliers = test_out$p.value,
      zero_inflation = test_zero$p.value
    ),
    all_pass = all_pass,
    sim_time = as.numeric(sim_time)
  ))
}

save_comparison_plot <- function(dharma_results, output_dir) {
  "Save comparison plot of all model types"
  
  dir.create(output_dir, showWarnings = FALSE, recursive = TRUE)
  
  plot_file <- file.path(output_dir, "model_comparison_dharma.png")
  
  n_models <- length(dharma_results)
  
  png(plot_file, width = 16, height = 4 * ceiling(n_models/2), units = "in", res = 150)
  par(mfrow = c(ceiling(n_models/2), 2))
  
  for (result in dharma_results) {
    plot(result$dharma_res, main = paste(result$model_name, "-", result$model_type))
  }
  
  dev.off()
  cat("Comparison plot saved:", plot_file, "\n")
}

# ============================================================================
# Main execution
# ============================================================================

main <- function() {
  cat("\n")
  cat(paste(rep("=", 70), collapse = ""), "\n")
  cat("IMPROVED DHARMA DIAGNOSTICS - TESTING MULTIPLE MODEL TYPES\n")
  cat(paste(rep("=", 70), collapse = ""), "\n\n")
  
  # Load cached data
  cache <- load_cache()
  df <- cache$data
  meta <- cache$meta
  
  # Build formula
  formula_str <- build_formula(meta)
  
  # Fit multiple model types
  models <- fit_multiple_models(formula_str, df)
  
  if (length(models) == 0) {
    cat("❌ No models fitted successfully!\n")
    return()
  }
  
  # Run DHARMa on each successful model
  cat(paste(rep("=", 70), collapse = ""), "\n")
  cat("DHARMA DIAGNOSTICS COMPARISON\n")
  cat(paste(rep("=", 70), collapse = ""), "\n\n")
  
  dharma_results <- list()
  for (name in names(models)) {
    dharma_results[[name]] <- run_dharma_test(models[[name]], name)
  }
  
  # Summary table
  cat(paste(rep("=", 70), collapse = ""), "\n")
  cat("SUMMARY COMPARISON\n")  
  cat(paste(rep("=", 70), collapse = ""), "\n\n")
  
  summary_df <- data.frame(
    Model = sapply(dharma_results, function(x) x$model_name),
    Type = sapply(dharma_results, function(x) x$model_type), 
    AIC = sapply(dharma_results, function(x) round(x$aic, 1)),
    Uniformity = sapply(dharma_results, function(x) sprintf("%.4f", x$tests$uniformity)),
    Dispersion = sapply(dharma_results, function(x) sprintf("%.4f", x$tests$dispersion)),
    Outliers = sapply(dharma_results, function(x) sprintf("%.4f", x$tests$outliers)),
    ZeroInfl = sapply(dharma_results, function(x) sprintf("%.4f", x$tests$zero_inflation)),
    Pass = sapply(dharma_results, function(x) ifelse(x$all_pass, "PASS", "FAIL"))
  )
  
  print(summary_df, row.names = FALSE)
  
  # Find best model
  passed_models <- dharma_results[sapply(dharma_results, function(x) x$all_pass)]
  
  if (length(passed_models) > 0) {
    best_model <- passed_models[[which.min(sapply(passed_models, function(x) x$aic))]]
    cat("\n🏆 Best model:", best_model$model_name, "(", best_model$model_type, ")")
    cat(" AIC:", round(best_model$aic, 1), "\n")
  } else {
    cat("\n⚠️  No models passed all DHARMa tests.\n")
    best_aic <- which.min(sapply(dharma_results, function(x) x$aic))
    cat("Lowest AIC:", dharma_results[[best_aic]]$model_name, 
        "(", dharma_results[[best_aic]]$model_type, ")",
        "AIC:", round(dharma_results[[best_aic]]$aic, 1), "\n")
  }
  
  # Save plots
  save_comparison_plot(dharma_results, OUTPUT_DIR)
  
  # Save summary
  summary_file <- file.path(OUTPUT_DIR, "model_comparison_summary.json")
  summary_json <- lapply(dharma_results, function(x) {
    list(
      model = x$model_name,
      type = x$model_type,
      aic = x$aic,
      theta = x$theta,
      tests = x$tests,
      pass = x$all_pass,
      simulation_time = x$sim_time
    )
  })
  write_json(summary_json, summary_file, pretty = TRUE)
  cat("\nSummary saved:", summary_file, "\n")
  
  cat("\n✅ Model comparison complete!\n\n")
}

# Run if executed directly
if (!interactive()) {
  main()
}